// Video binary verisini base64'e çevir
const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64Video = binaryData.toString('base64');

// Notion'dan gelen bilgileri al
const notionItem = $('📋 Notion - Bekleyen Al').first().json;
const contentUrl = notionItem.property_url || 'URL yok';
const title = notionItem.property_title || notionItem.name || 'Başlık yok';

// Kategorize prompt
const prompt = `Sen bir içerik sınıflandırma uzmanısın. Bu videoyu KARE KARE izle — ses, görüntü, ekrandaki yazılar, konuşan kişinin kim olduğu — her şeyi incele. Sonra içeriği SADECE aşağıdaki kategorilerden birine ata.

VİDEOYU İZLERKEN ŞUNLARA DİKKAT ET:
- Videoda kim var? Bir emlakçı mı, bir YouTuber mı, bir eğitimci mi, bir sporcu mu?
- Ekranda ne gösteriliyor? Bir ev/mülk mü, bir yazılım arayüzü mü, spor hareketi mi, sosyal medya ekranları mı?
- Kişi ne anlatıyor? Bir araç mı tanıtıyor, sosyal medya stratejisi mi öğretiyor, ev mi satıyor, ilham mı veriyor?
- Videonun AMACI ne? Eğitim mi, satış mı, ilham mı, demo mu?

KATEGORİLER VE KURALLARI:

"Lettings" → Bir emlakçının mülk tanıttığı, ev turu yaptığı, emlak sektörüne özel içerik ürettiği videolar. Kişisel marka videoları, komisyon hikayeleri, müşteri ilişkileri, "day in the life of a real estate agent" tarzı videolar da dahil.

"Inspiration" → Yaratıcı, ilham verici, viral potansiyelli, "bunu uyarlayarak kendi içeriğimizi çekebiliriz" dedirten videolar. AI ile üretilmiş sanat veya video örnekleri, dikkat çekici montaj teknikleri, emlakla alakası olmayan ama uyarlamaya değer.

"Social Media" → Sosyal medya platformlarının algoritma güncellemelerini, SM yönetim stratejilerini, engagement taktiklerini, hashtag ve SEO bilgilerini ANLATAN/ÖĞRETEN videolar. hook stratejileri gösteren içerikler. İçerik "nasıl daha çok kişiye ulaşırsın" sorusunu cevaplıyorsa buraya.

"Learning" → Yeni bir AI aracını, bir teknolojiyi veya bir yazılımı TANITIYORSA ve nasıl kullanılacağını ÖĞRETİYORSA buraya ata. Tool demo, tutorial, kurs videoları. Örneğin HeyGen, Runway, ElevenLabs demo videoları.

"Automation" → n8n, Make.com, Zapier gibi otomasyon araçlarını, API entegrasyonlarını veya workflow kurulumlarını gösteren videolar.

"Sport" → Spor hareketleri, fitness, antrenman, egzersiz gösteren, hareket formu anlatan videolar.

"Investment" → Yatırım, finans, vergi avantajları, piyasa analizi, emlak yatırım getirisi anlatan videolar.

"App" → Mobil uygulama veya masaüstü yazılım incelemeleri (AI/otomasyon değilse). Genel amaçlı uygulama tanıtımları, app stratejileri.

"Random" → Yukarıdaki kategorilerin hiçbirine NET olarak uymuyorsa.

ÖNEMLI KURALLAR:
- Bir emlakçı komik bir video çekmiş olabilir ama özünde emlak işi anlatıyorsa → "Lettings"
- Bir video genel spesifik bir araç öğretiyorsa → "Learning"  
- Emin olamıyorsan confidence değerini düşük tut (0.5 altı)

İçerik Başlığı: ${title}
İçerik Linki: ${contentUrl}

SADECE şu JSON formatında cevap ver, BAŞKA HİÇBİR ŞEY YAZMA:
{"category": "KATEGORİ_ADI", "confidence": 0.85, "detected_elements": "Videoda tespit edilen unsurlar: kim var, ne gösteriliyor, ekrandaki yazılar...", "reason": "Neden bu kategoriye atıldığının kısa açıklaması"}`;

// Gemini API request body oluştur
const requestBody = {
  contents: [
    {
      parts: [
        {
          inlineData: {
            mimeType: "video/mp4",
            data: base64Video
          }
        },
        {
          text: prompt
        }
      ]
    }
  ],
  generationConfig: {
    temperature: 0.15,
    maxOutputTokens: 1024,
    responseMimeType: "application/json"
  }
};

return [{ json: { requestBody } }];

const validCategories = [
  'Lettings', 'Inspiration', 'Social Media', 'Learning',
  'Automation', 'Sport', 'Investment', 'App', 'Random'
];

try {
  const responseText = $input.first().json.candidates[0].content.parts[0].text;

  // Markdown formatting temizle
  const cleanText = responseText
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();

  const parsed = JSON.parse(cleanText);

  // Geçerli kategori kontrolü
  if (!validCategories.includes(parsed.category)) {
    parsed.reason = 'Orijinal kategori (' + parsed.category + ') geçersiz, Random atandı';
    parsed.category = 'Random';
  }

  // Confidence sayıya çevir
  parsed.confidence = Number(parsed.confidence) || 0;

  return [{ json: parsed }];

} catch (e) {
  // Hata durumunda güvenli fallback
  return [{ json: {
    category: 'Random',
    confidence: 0,
    detected_elements: 'HATA: Gemini yanıtı parse edilemedi',
    reason: 'Parse hatası: ' + e.message + ' | Ham yanıt: ' + 
            String($input.first().json?.candidates?.[0]?.content?.parts?.[0]?.text || 'boş').substring(0, 300)
  }}];
}

// Notion'dan gelen video linki
const url = $('📋 Notion - Bekleyen Al').first().json.property_url || '';

// Platform tespiti ve uygun Apify Actor ID eşleştirmesi
// ⚠️ Her actor ID'yi Apify Store'dan alıp buraya yapıştır
const platformMap = {
  instagram: {
    actorId: 'shu8hvrXbJbY3Eb9W',  // ⚠️ Apify Store'dan: "Instagram Reel Scraper"
    bodyKey: 'directUrls',           // Actor'ün beklediği input key
    platform: 'instagram'
  },
  facebook: {
    actorId: 'PBJEdJdctLHQaqdfe',   // ⚠️ Apify Store'dan: "Facebook Video Downloader"
    bodyKey: 'startUrls',
    platform: 'facebook'
  },
  youtube: {
    actorId: 'h7sDV53CddomktSi5', // ⚠️ Apify Store'dan
    bodyKey: 'startUrls',
    platform: 'youtube'
  },
  tiktok: {
    actorId: '7200360993149553925', // ⚠️ Apify Store'dan
    bodyKey: 'postURLs',
    platform: 'tiktok'
  }
};

// URL'den platform tespit et
let detected = 'unknown';
if (url.includes('instagram.com')) {
  detected = 'instagram';
} else if (url.includes('facebook.com') || url.includes('fb.watch')) {
  detected = 'facebook';
} else if (url.includes('youtube.com') || url.includes('youtu.be')) {
  detected = 'youtube';
} else if (url.includes('tiktok.com') || url.includes('vm.tiktok.com')) {
  detected = 'tiktok';
}

const config = platformMap[detected];

if (!config) {
  // Bilinmeyen platform — hata fırlatma, loglayıp geç
  return [{
    json: {
      error: true,
      platform: 'unknown',
      url: url,
      message: 'Desteklenmeyen platform: ' + url
    }
  }];
}

// Apify API URL'si ve body'yi hazırla
const apifyToken = 'ENV_APIFY_TOKEN';
const apifyUrl = `https://api.apify.com/v2/acts/${config.actorId}/run-sync-get-dataset-items?token=${apifyToken}`;

// Her actor farklı input formatı bekliyor
let requestBody = {};

if (detected === 'instagram') {
  requestBody = {
    directUrls: [url],
    resultsType: 'posts'
  };
} else if (detected === 'facebook') {
  requestBody = {
    startUrls: [{ url: url }]
  };
} else if (detected === 'youtube') {
  requestBody = {
    startUrls: [{ url: url }],
    maxResults: 1
  };
} else if (detected === 'tiktok') {
  requestBody = {
    postURLs: [url]
  };
}

return [{
  json: {
    error: false,
    platform: detected,
    url: url,
    apifyUrl: apifyUrl,
    requestBody: requestBody
  }
}];
